@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (type == null || value == null) {
        throw new IllegalArgumentException("Type and value cannot be null");
    }
    if (!Character.class.isAssignableFrom(type) && type != char.class) {
        throw new IllegalArgumentException("Type must be Character or char");
    }
    if (value instanceof Character) {
        return value;
    } else if (value instanceof String) {
        String strValue = (String) value;
        if (strValue.length() != 1) {
            throw new IllegalArgumentException("String value must be of length 1 to convert to Character");
        }
        return strValue.charAt(0);
    } else if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    } else {
        throw new IllegalArgumentException("Cannot convert value of type " + value.getClass().getName() + " to Character");
    }
}

