        for (int i = end; i < headerPart.length() - 1; i++) {
            if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
                return i; // Return the index of \r
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        // This exception should not occur due to the checks above, but handle it just in case
        return -1;
    }

    return -1; // No \r\n sequence found
}

