public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 2) {
        return 2;
    }
    int maxCapacity = desiredCapacity;
    if (desiredCapacity >= 1000) {
        maxCapacity = (int) (desiredCapacity * 1.11);
    }
    int candidate = desiredCapacity;
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        if (candidate >= maxCapacity) {
            throw new IllegalArgumentException("No prime number found within 11% of desired capacity.");
        }
        candidate++;
    }
}

